/**
 * vendor/mammoth.browser.min.js
 * Standalone mammoth.js loader wrapper for Chrome Extension on-device DOCX extraction.
 */
(function(global) {
  'use strict';
  if (!global.mammoth) {
    global.mammoth = {
      extractRawText: async function(options) {
        if (options && options.arrayBuffer && typeof global.extractDocxText === 'function') {
          const uint8 = new Uint8Array(options.arrayBuffer);
          const res = global.extractDocxText(uint8);
          return { value: res.fullText || '' };
        }
        return { value: '' };
      }
    };
  }
})(typeof self !== 'undefined' ? self : globalThis);
